from typing import List, Tuple

def f(N: int, M: int, bridges: List[Tuple[int, int, int]]) -> int:
    '''
    N: an integer
    M: an integer
    bridges: a list of tuples, where each tuple contains three integers
    '''
    heavily_ugly_factors = set()

    for S, D, C in bridges:
        for poss_factor in range(1, min(D, S) + 1):
            if S % poss_factor > 0 and D % poss_factor == 0:
                heavily_ugly_factors.add(poss_factor)
        if S > D:
            S, D = D, S
        if C in heavily_ugly_factors:
            heavily_ugly_factors.remove(C)

    return len(heavily_ugly_factors)
